select public.admin_notify('🔔 Chrome wali aakhri rukawat fix', 'Dusre browser me push aa gaya = poori pipeline aapke phone par sahi kaam karti hai. Chrome me bas EK setting bakhi thi: "Collapse all requests" ki wajah se Allow-popup dikhta hi nahi tha. Ab panel me naya waiting-box hai jo URL bar ke bell-chip tak rahbari karta hai aur 45s khud intzar karta hai. Sabse pakka: Chrome Settings → Site settings → Notifications → "Expand all requests" chunein → panel me 📲 → ▶ → BADA popup → Allow. Test push turant aayegi.', 'session_end') as notified;
